diff --git a/build.xml b/build.xml
index 682c1f28a..f7b69b95f 100644
--- a/build.xml
+++ b/build.xml
@@ -14,8 +14,8 @@
  limitations under the License.
 -->
 <project name="compiler" basedir="." default="jar">
-<property name="ant.build.javac.target" value="1.6"/>
-<property name="ant.build.javac.source" value="1.6"/>
+<property name="ant.build.javac.target" value="1.8"/>
+<property name="ant.build.javac.source" value="1.8"/>

   <!-- define other variables -->
   <property name="src.dir" value="${basedir}/src" />
diff --git a/src/com/google/javascript/jscomp/MakeDeclaredNamesUnique.java b/src/com/google/javascript/jscomp/MakeDeclaredNamesUnique.java
index 79f2247dd..8b8e1529e 100644
--- a/src/com/google/javascript/jscomp/MakeDeclaredNamesUnique.java
+++ b/src/com/google/javascript/jscomp/MakeDeclaredNamesUnique.java
@@ -315,21 +315,45 @@ class MakeDeclaredNamesUnique
      * values.
      */
         // Check if the new name is valid and if it would cause conflicts.
-            if (var.scope.isDeclared(newName, recurseScopes) ||
+            // First check ancestor scopes (always recurse)
+            if (var.scope.isDeclared(newName, true) ||
                 !TokenStream.isJSIdentifier(newName)) {
               newName = oldName;
             } else {
-              var.scope.declare(newName, var.nameNode, null, null);
-          // Adding a reference to the new name to prevent either the parent
-          // scopes or the current scope renaming another var to this new name.
-              Node parentNode = var.getParentNode();
-              if (parentNode.getType() == Token.FUNCTION &&
-                  parentNode == var.scope.getRootNode()) {
-                var.getNameNode().setString(newName);
+              // Also check if any descendant scope has already reverted to this name
+              // (we can't revert in parent if descendants have reverted to it)
+              boolean hasConflict = false;
+              for (Var mapVar : nameMap.keySet()) {
+                if (nameMap.get(mapVar).equals(newName)) {
+                  // Check if mapVar's scope is a descendant of current var's scope
+                  // i.e., can we reach var.scope by going up from mapVar.scope?
+                  Scope s = mapVar.scope.getParent();
+                  while (s != null) {
+                    if (s == var.scope) {
+                      hasConflict = true;
+                      break;
+                    }
+                    s = s.getParent();
+                  }
+                  if (hasConflict) break;
+                }
               }
-              node.setString(newName);
-          compiler.reportCodeChange();
-        }
+
+              if (hasConflict) {
+                newName = oldName;
+              } else {
+                var.scope.declare(newName, var.nameNode, null, null);
+            // Adding a reference to the new name to prevent either the parent
+            // scopes or the current scope renaming another var to this new name.
+                Node parentNode = var.getParentNode();
+                if (parentNode.getType() == Token.FUNCTION &&
+                    parentNode == var.scope.getRootNode()) {
+                  var.getNameNode().setString(newName);
+                }
+                node.setString(newName);
+            compiler.reportCodeChange();
+              }
+            }

             nameMap.put(var, newName);
